/* generated by extract.py from ../../Core/DSP/Instruments/InstrumentManager.c */
uint8_t instrumentManager_targetValid(uint8_t scene_index,
                                      instrument_param_id_t id,
                                      instrument_target_use_t use)
{
    const kit_instrument_slot_t *slot;
    const ParamDescriptor *descriptor;
    uint8_t target_slot;
    /*
     * Validate the complete automation namespace.
     *
     * Inputs: a canonical target ID and requested use. Voice IDs continue
     * through the registry-driven descriptor checks below; Scene IDs are
     * validated by the Scene-target table because they have no instrument
     * descriptor. Output: Scene targets and Effect block-7 targets are legal
     * for automation when their owners mark them valid; other non-voice IDs
     * remain invalid. Affiliate: PatternData's packed automation writer and
     * the STEP target picker.
     */
    if (!instrumentParam_isVoiceParameter(id)) {
        /* Effect automation is validated by the active Scene's registry. */
        if (use == INSTRUMENT_TARGET_AUTOMATION &&
            effectTarget_isEffectId(id))
            return effects_targetValid(scene_index, id, use);
        if (use == INSTRUMENT_TARGET_AUTOMATION &&
            id >= INSTRUMENT_VOICE_ID_COUNT &&
            id < INSTRUMENT_TOTAL_ID_COUNT)
            return sceneModTarget_isSceneTarget(id);
        return 0u;
    }
    target_slot = instrumentParam_slot(id);
    slot = scene_instrumentSlotConst(scene_index, target_slot);
    if (!slot)
        return 0u;
    descriptor = instrumentManager_descriptor(slot->type,
                                               instrumentParam_local(id));
    /*
     * Selector rows are automation targets only (S087 stage B).
     *
     * What:       a voice row must be MORPHABLE to be any target, except a
     *             SELECTOR row with AUTOMATABLE set, which is valid for
     *             INSTRUMENT_TARGET_AUTOMATION only. Modulation (LFO,
     *             velocity) still requires MORPHABLE and MODULATABLE.
     * Why:        S087 P0 §12.5: typ is step-automatable, one value per step,
     *             but never an LFO/velocity target and never morphed.
     * Inputs:     descriptor flags, use.  Outputs: validity.
     * Accessors:  every caller of this gate: sequencer.c (drain, ramp
     *             service); menu.c (automation target picker, live record,
     *             display); PatternData.c (step writer);
     *             InstrumentManager.c (runtime and target resolution).
     * Affiliates: INSTRUMENT_PARAM_FLAG_SELECTOR; seq_rampDtypeOk().
     */
    if (!descriptor)
        return 0u;
    if (!(descriptor->flags & INSTRUMENT_PARAM_FLAG_MORPHABLE)) {
        if (use == INSTRUMENT_TARGET_AUTOMATION &&
            0 &&
            (descriptor->flags & INSTRUMENT_PARAM_FLAG_AUTOMATABLE))
            return 1u;
        return 0u;
    }
    if (use == INSTRUMENT_TARGET_MODULATION) {
        /*
         * Modulation targets are either direct runtime fields for the
         * ModulationNode pointer backend or explicit supplemental descriptor
         * targets with their own adapter. Slot decimation is the first
         * supplemental voice target: it is descriptor-owned and image-backed,
         * but applies through mixer_decimation_rate[slot] rather than a
         * voice-struct member pointer. Keeping both cases in the shared
         * validator makes Menu target stepping and DSP target installation
         * agree without a hardcoded parameter list.
         */
        return (uint8_t)(((descriptor->flags & INSTRUMENT_PARAM_FLAG_MODULATABLE) != 0u) &&
                         ((descriptor->runtime.kind == INSTRUMENT_BIND_INSTANCE_OFFSET &&
                           instrumentManager_descriptorSupportsModulationRange(descriptor)) ||
                          instrumentManager_descriptorIsSlotDecimationTarget(descriptor)));
    }
    return (uint8_t)((descriptor->flags & INSTRUMENT_PARAM_FLAG_AUTOMATABLE) != 0u);
}
